// Writes mobile/src/engine/mmcal.js: the vendored mmcal engine as an ES module
// for the React Native app (same source the web calendar and posters use).
import { writeFileSync, mkdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { engineSource } from './engine.mjs';

const out = fileURLToPath(new URL('../mobile/src/engine/mmcal.js', import.meta.url));
mkdirSync(new URL('../mobile/src/engine/', import.meta.url), { recursive: true });
const header = `/* eslint-disable */
// GENERATED by scripts/build-mobile-engine.mjs from vendor/mmcal/ceMmDateTime.js
// mmcal — Modern Myanmar Calendrical Calculations, Dr. Yan Naing Aye, MIT License.
// Do not edit by hand.
`;
writeFileSync(out, header + engineSource() + '\nexport { ceDateTime, ceMmDateTime, ceMmTranslate };\n');
console.log('wrote', out);
